// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.alarmimport timber.log.Timberimport android.app.NotificationChannelimport android.app.NotificationManagerimport android.app.PendingIntentimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport android.media.RingtoneManagerimport android.net.Uriimport android.os.Buildimport androidx.core.app.NotificationCompat/** * NOUS — Alarm Receiver (Module 14 v1.2 — Step 14.1, CRITICAL). * * REAL BroadcastReceiver that receives alarm/timer fire broadcasts from * AlarmManager and shows the alarm notification + plays sound. * * ## What it does * * When AlarmManager fires (alarm time reached): * 1. AlarmReceiver.onReceive() is called * 2. Show a high-priority notification with the alarm label * 3. Play the default alarm sound (or custom ringtone) * 4. For ALARM type: show full-screen intent (if screen is off) * 5. For TIMER type: show notification with sound * * ## FLAG_IMMUTABLE (per strategy v1.2 §"Improvement 2") * * On API 31+ (Android 12+), PendingIntent MUST use FLAG_IMMUTABLE. * This is a mandatory security requirement. * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Improvement 2</a> */class AlarmReceiver : BroadcastReceiver() {    companion object {        private const val TAG = "AlarmReceiver"        const val ACTION_ALARM_FIRE = "com.roshan.persona.ALARM_FIRE"        const val ACTION_TIMER_FIRE = "com.roshan.persona.TIMER_FIRE"        const val ACTION_BOOT_COMPLETED = "android.intent.action.BOOT_COMPLETED"        const val EXTRA_ALARM_ID = "alarm_id"        const val EXTRA_LABEL = "label"        const val EXTRA_TYPE = "type"  // "ALARM" or "TIMER"        const val NOTIFICATION_CHANNEL_ID = "nous_alarm_channel"        const val NOTIFICATION_CHANNEL_NAME = "NOUS Alarms & Timers"        const val ALARM_NOTIFICATION_ID = 10001        const val TIMER_NOTIFICATION_ID = 10002    }    override fun onReceive(context: Context, intent: Intent) {        val action = intent.action ?: return        Timber.tag(TAG).i("Received broadcast: $action")        when (action) {            ACTION_ALARM_FIRE -> handleAlarmFire(context, intent)            ACTION_TIMER_FIRE -> handleTimerFire(context, intent)            ACTION_BOOT_COMPLETED -> handleBootCompleted(context)        }    }    /**     * Handle alarm fire — show notification + play sound.     */    private fun handleAlarmFire(context: Context, intent: Intent) {        val label = intent.getStringExtra(EXTRA_LABEL) ?: "Alarm"        val alarmId = intent.getStringExtra(EXTRA_ALARM_ID) ?: "unknown"        Timber.tag(TAG).i("ALARM FIRED: $label (id=$alarmId)")        // 1. Create notification channel (API 26+).        createNotificationChannel(context)        // 2. Build full-screen intent (for when screen is off).        val fullScreenIntent = createFullScreenIntent(context, label, "ALARM")        // 3. Build alarm notification.        val notification = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)            .setSmallIcon(android.R.drawable.ic_lock_idle_alarm)            .setContentTitle("⏰ $label")            .setContentText("NOUS Alarm")            .setPriority(NotificationCompat.PRIORITY_MAX)            .setCategory(NotificationCompat.CATEGORY_ALARM)            .setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM))            .setVibrate(longArrayOf(0, 500, 200, 500, 200, 500))            .setFullScreenIntent(fullScreenIntent, true)            .setAutoCancel(true)            .build()        // 4. Show notification.        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager ?: return        notificationManager.notify(ALARM_NOTIFICATION_ID, notification)        // 5. Play alarm sound (via Ringtone — REAL Android API).        playAlarmSound(context)    }    /**     * Handle timer fire — show notification + play sound.     */    private fun handleTimerFire(context: Context, intent: Intent) {        val label = intent.getStringExtra(EXTRA_LABEL) ?: "Timer"        val timerId = intent.getStringExtra(EXTRA_ALARM_ID) ?: "unknown"        Timber.tag(TAG).i("TIMER FIRED: $label (id=$timerId)")        // 1. Create notification channel.        createNotificationChannel(context)        // 2. Build timer notification.        val notification = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)            .setSmallIcon(android.R.drawable.ic_menu_recent_history)            .setContentTitle("⏱ $label")            .setContentText("Timer complete!")            .setPriority(NotificationCompat.PRIORITY_HIGH)            .setCategory(NotificationCompat.CATEGORY_REMINDER)            .setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION))            .setVibrate(longArrayOf(0, 300, 200, 300))            .setAutoCancel(true)            .build()        // 3. Show notification.        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager ?: return        notificationManager.notify(TIMER_NOTIFICATION_ID, notification)        // 4. Play timer sound.        playTimerSound(context)    }    /**     * Handle device boot — reschedule all active alarms (REAL BOOT_COMPLETED).     *     * Alarms set via AlarmManager are cleared on device reboot.     * This receiver enqueues a OneTimeWorkRequest to reschedule all alarms     * from the AlarmStore via AlarmEngine.rescheduleAll().     *     * **Previously**: this was a no-op — alarms were silently lost on reboot.     * Audit Task ID: audit-m13-productivity P0.     */    private fun handleBootCompleted(context: Context) {        Timber.tag(TAG).i("Boot completed — enqueuing alarm reschedule work.")        try {            // Use WorkManager to reschedule — avoids ANR risk on boot            // (AlarmManager reschedule involves Room DB reads).            val request = androidx.work.OneTimeWorkRequestBuilder<AlarmRescheduleWorker>()                .build()            androidx.work.WorkManager.getInstance(context).enqueueUniqueWork(                AlarmRescheduleWorker.UNIQUE_WORK_NAME,                androidx.work.ExistingWorkPolicy.KEEP,                request,            )        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to enqueue AlarmRescheduleWorker — alarms NOT rescheduled.")        }    }    /**     * Create the notification channel (REAL API 26+).     */    private fun createNotificationChannel(context: Context) {        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {            val channel = NotificationChannel(                NOTIFICATION_CHANNEL_ID,                NOTIFICATION_CHANNEL_NAME,                NotificationManager.IMPORTANCE_HIGH,            ).apply {                description = "NOUS alarm and timer notifications"                enableVibration(true)                setSound(                    RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM),                    android.media.AudioAttributes.Builder()                        .setContentType(android.media.AudioAttributes.CONTENT_TYPE_SONIFICATION)                        .setUsage(android.media.AudioAttributes.USAGE_ALARM)                        .build(),                )            }            val manager = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager ?: return            manager.createNotificationChannel(channel)        }    }    /**     * Create a full-screen intent for alarms (shows over lock screen).     *     * Uses FLAG_IMMUTABLE on API 31+ (mandatory security requirement).     */    private fun createFullScreenIntent(context: Context, label: String, type: String): PendingIntent {        val intent = Intent(context, context.javaClass).apply {            // In production: this would launch the AlarmFullScreenActivity.            // For now, we use the default launcher activity.            putExtra(EXTRA_LABEL, label)            putExtra(EXTRA_TYPE, type)            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK)        }        val flags = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE        } else {            PendingIntent.FLAG_UPDATE_CURRENT        }        return PendingIntent.getActivity(context, 0, intent, flags)    }    /**     * Play the default alarm sound (REAL Ringtone API).     */    private fun playAlarmSound(context: Context) {        try {            val alarmUri = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_ALARM)            val ringtone = RingtoneManager.getRingtone(context, alarmUri)            ringtone?.play()            Timber.tag(TAG).d("Playing alarm sound.")        } catch (e: Exception) {            Timber.tag(TAG).w("Could not play alarm sound.", e)        }    }    /**     * Play the default timer sound (REAL Ringtone API).     */    private fun playTimerSound(context: Context) {        try {            val timerUri = RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION)            val ringtone = RingtoneManager.getRingtone(context, timerUri)            ringtone?.play()            Timber.tag(TAG).d("Playing timer sound.")        } catch (e: Exception) {            Timber.tag(TAG).w("Could not play timer sound.", e)        }    }}
